// Midian (#18): il pulsante GUILD del paperdoll. Nei file grafici del client di Midian (1.26) la gump 0x57b2 dei client
// nuovi non c'e' e non c'e' nessuna scritta "guild" nello stile dei pulsanti: l'immagine (normale, premuto, sopra) e' il
// fondo comune dei pulsanti del paperdoll (0x7d6-0x7eb, il colore piu' frequente pixel per pixel) con "Guild" scritto
// col font ASCII 1 del client. 64x21, RGBA. Fatta con tools/midian-pulsante-gilda/cuoci.js.
using System;
using Microsoft.Xna.Framework.Graphics;

namespace ClassicUO.Game.UI.Controls
{
    internal static class MidianPulsanteGilda
    {
        public const int LARGHEZZA = 64, ALTEZZA = 21;
        private static Texture2D[] _immagini;

        public static Texture2D[] Immagini
        {
            get
            {
                if (_immagini == null || _immagini[0].IsDisposed)
                {
                    _immagini = new Texture2D[DATI.Length];
                    for (int i = 0; i < DATI.Length; i++)
                    {
                        _immagini[i] = new Texture2D(Client.Game.GraphicsDevice, LARGHEZZA, ALTEZZA, false, SurfaceFormat.Color);
                        _immagini[i].SetData(Convert.FromBase64String(DATI[i]));
                    }
                }
                return _immagini;
            }
        }

        private static readonly string[] DATI =
        {
            "",
            "",
            ""
        };
    }
}
